// ControlServer is the server API for Control service.
// All implementations must embed UnimplementedControlServer
// for forward compatibility.
type ControlServer interface {
	// CreateInstance creates the actor from the box's golden template tag, registers the instance with the
	// credential provider, applies its EgressPolicy and resumes it. Idempotent on instance_id. Returns once the
	// gateway has accepted the work; progress arrives through Ingest.ReportInstanceStatus.
	CreateInstance(context.Context, *CreateInstanceRequest) (*CreateInstanceResponse, error)
	// StartFromSnapshot is CreateInstance from a snapshot's tag.
	StartFromSnapshot(context.Context, *StartFromSnapshotRequest) (*CreateInstanceResponse, error)
	// CancelInstance stops the instance for good: deletes the actor (and with it the transcript on its workspace
	// volume) and egress policy and revokes cached credentials. Snapshots are kept.
	CancelInstance(context.Context, *InstanceActionRequest) (*InstanceActionResponse, error)
	// SuspendInstance settles in-flight entities, closes the event subscription and suspends the actor.
	SuspendInstance(context.Context, *InstanceActionRequest) (*InstanceActionResponse, error)
	// ResumeInstance resumes a suspended actor and re-subscribes to its events (resume-on-open/prompt).
	ResumeInstance(context.Context, *InstanceActionRequest) (*InstanceActionResponse, error)
	// SnapshotInstance runs prepare (settle, scrub credentials), synchronous suspend, CreateTag, resume. Returns
	// when accepted; the result arrives through Ingest.ReportSnapshot.
	SnapshotInstance(context.Context, *SnapshotInstanceRequest) (*SnapshotInstanceResponse, error)
	// DeleteSnapshot deletes the snapshot's Substrate tag.
	DeleteSnapshot(context.Context, *DeleteSnapshotRequest) (*DeleteSnapshotResponse, error)
	// SetAgentBilling restarts one agent connection with different billing ("Switch to Plural AI proxy") and
	// resumes its threads.
	SetAgentBilling(context.Context, *SetAgentBillingRequest) (*SetAgentBillingResponse, error)
	// RebaseInstance moves an instance to another template revision of its runner, normally the current one: a
	// new environment image or a new devbox-daemon. A running instance is suspended (synchronously), pointed at
	// the revision's template and resumed, which cold-boots it: processes and root filesystem changes are lost,
	// the home volume and agent threads are kept. A suspended instance is only pointed at the template and
	// cold-boots at its next resume. If it doesn't start on the new revision it is returned to the one it had,
	// from its last snapshot. Returns when accepted; the result arrives through Ingest.ReportInstanceStatus.
	RebaseInstance(context.Context, *RebaseInstanceRequest) (*RebaseInstanceResponse, error)
	// CreateThread: `session/new` (plus `session/set_config_option` for model and initial options).
	CreateThread(context.Context, *CreateThreadRequest) (*ThreadResponse, error)
	// ListThreads: the daemon's threads plus, when requested, importable sessions from `session/list`.
	ListThreads(context.Context, *ListThreadsRequest) (*ListThreadsResponse, error)
	// ImportThread: `session/resume` with `replayFrom: start` (or `session/load` on v1) for a listed session.
	ImportThread(context.Context, *ImportThreadRequest) (*ThreadResponse, error)
	// ResumeThread: reopen a closed thread, `session/resume` (or `session/load`).
	ResumeThread(context.Context, *ResumeThreadRequest) (*ThreadResponse, error)
	// CloseThread: `session/close` (or cancel + drop on agents without close).
	CloseThread(context.Context, *ThreadActionRequest) (*ThreadResponse, error)
	// DeleteThread: `session/delete` when supported; `agent_side_deleted` says whether it was.
	DeleteThread(context.Context, *ThreadActionRequest) (*DeleteThreadResponse, error)
	// ForkThread: `session/fork` or `unstable_forkSession`. UNSUPPORTED when not advertised.
	ForkThread(context.Context, *ForkThreadRequest) (*ThreadResponse, error)
	// Prompt sends `session/prompt`. Returns once the daemon accepted (or queued) it; the turn's progress arrives
	// as entities and `state_update`. Idempotent on prompt_id.
	Prompt(context.Context, *PromptRequest) (*PromptResponse, error)
	// CancelPrompt sends `session/cancel` for the thread's current turn.
	CancelPrompt(context.Context, *CancelPromptRequest) (*CancelPromptResponse, error)
	// UpdateQueuedPrompt edits, drops or promotes a prompt still held in the thread's queue.
	UpdateQueuedPrompt(context.Context, *UpdateQueuedPromptRequest) (*UpdateQueuedPromptResponse, error)
	// SetThreadConfigOption: `session/set_config_option`. Returns the agent's reported options.
	SetThreadConfigOption(context.Context, *SetThreadConfigOptionRequest) (*SetThreadConfigOptionResponse, error)
	// RespondInteraction answers a pending permission request or elicitation.
	RespondInteraction(context.Context, *RespondInteractionRequest) (*RespondInteractionResponse, error)
	// ListCommands returns the session's live slash commands (running instances only).
	ListCommands(context.Context, *ListCommandsRequest) (*ListCommandsResponse, error)
	// GetTimeline pages a session's settled entities by position, merged with in-flight state.
	GetTimeline(context.Context, *GetTimelineRequest) (*GetTimelineResponse, error)
	// GetSessions returns the thread and subagent tree.
	GetSessions(context.Context, *GetSessionsRequest) (*GetSessionsResponse, error)
	// SetInstanceLeases replaces the instance's viewer and deferral leases (section 4.3a).
	SetInstanceLeases(context.Context, *SetInstanceLeasesRequest) (*SetInstanceLeasesResponse, error)
	AddRepository(context.Context, *AddRepositoryRequest) (*AddRepositoryResponse, error)
	ListRepositories(context.Context, *ListRepositoriesRequest) (*ListRepositoriesResponse, error)
	ListFiles(context.Context, *ListFilesRequest) (*ListFilesResponse, error)
	ReadFile(context.Context, *ReadFileRequest) (*ReadFileResponse, error)
	WriteFile(context.Context, *WriteFileRequest) (*WriteFileResponse, error)
	GetChanges(context.Context, *GetChangesRequest) (*GetChangesResponse, error)
	// PreparePullRequest readies a checkout for a pull request in the box (see PreparePullRequestRequest).
	PreparePullRequest(context.Context, *PreparePullRequestRequest) (*PreparePullRequestResponse, error)
	// OpenStream prepares a terminal, VNC or preview target and returns a short-lived descriptor. Console mints
	// the stream token around it; the browser then connects to KAS at /ext/devbox/streams/... (section 4.6).
	OpenStream(context.Context, *OpenStreamRequest) (*OpenStreamResponse, error)
	// InvalidateAllowlist drops the gateway's cached repository allowlist for a box or instance, and re-applies
	// egress policies, after console changes the runner or workbench repositories.
	InvalidateAllowlist(context.Context, *InvalidateAllowlistRequest) (*InvalidateAllowlistResponse, error)
	mustEmbedUnimplementedControlServer()
}

